CREATE TABLE IF NOT EXISTS cars (id SERIAL PRIMARY KEY,brand VARCHAR(50) NOT NULL,model VARCHAR(80) NOT NULL,year INTEGER NOT NULL,engine VARCHAR(30),transmission VARCHAR(30),mileage INTEGER DEFAULT 0,price BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
